package com.example.rokidkeyboardbridge;
public final class ComfortPoseTest {
 static int n;static void ok(boolean v,String m){n++;if(!v)throw new AssertionError(m);}
 public static void main(String[] args){long now=10000;EmbodiedScenePolicy p=new EmbodiedScenePolicy();for(int pose=0;pose<4;pose++){String q=ComfortPoseIntent.COMMANDS[pose];ok(ComfortPoseIntent.action(q)==pose,"explicit command");ok(ComfortPoseIntent.action("ロキ、"+q+"ください")==pose,"voice prefix and polite");ok(EmbodiedScenePolicy.visualCommand(q),"visual operation");p.user(q,now);ok(p.correctedRest()&&p.restMotion(now)==8+pose,"new pose is active");p.answer(ComfortPoseIntent.reply(pose),FullBodyPoseCatalog.Kind.NEUTRAL,now+100);ok(p.restMotion(now+100)==8+pose,"spoken confirmation cannot undo pose");p.user("今日はどんな日？",now+200);ok(p.restMotion(now+200)==8+pose,"ordinary question preserves pose");p.user("うれしい顔にして",now+300);ok(p.restMotion(now+300)==8+pose&&p.restFacePinned()&&p.restFace()==6,"manual face preserves comfort pose");p.user("驚いた顔にして",now+350);ok(p.restFace()==6&&p.restMotion(now+350)==8+pose,"unavailable expression never pretends to switch");p.user("表情をおまかせにして",now+400);ok(p.restMotion(now+400)==8+pose&&!p.restFacePinned(),"automatic face preserves pose");p.user("身じろぎを止めて",now+500);ok(p.restMotion(now+500)==8+pose,"stop motion preserves pose");ok(p.moving(now+500)==false,"stopped pose has no entry motion");now+=10000;}
 String[] no={"膝を抱えるとは？","うつ伏せで本を読んでと言った","彼女が横向きで休んでいる","私はストレッチしている","膝を抱えて座ってほしくない","軽くストレッチしないで","うつ伏せの画像を検索して","開脚して","四つん這いになって","膝を抱えて座って？","友人に横向きで休んでと言われた"};for(String q:no)ok(ComfortPoseIntent.action(q)<0,"not an instruction "+q);
 p.user(ComfortPoseIntent.COMMANDS[0],now);p.user(ComfortPoseIntent.COMMANDS[2],now+100);p.user("一つ前の姿勢に戻して",now+200);ok(p.restMotion(now+200)==8,"undo returns actual prior comfort pose");p.user("立って",now+300);ok(!p.correctedRest(),"explicit standing exits");p.user("ねそべって",now+400);ok(p.restMotion(now+400)==0,"old lying command remains old lying");
 for(int pose=0;pose<4;pose++)ok(Math.abs(ComfortPoseGeometry.scale(pose,240,520)*ComfortPoseGeometry.HEAD_WIDTH[pose]-CharacterViewport.standingHead(240,520))<.01f,"bent poses never enlarge the head to fill the viewport");
 for(int pose=0;pose<4;pose++)for(int variant=0;variant<4;variant++){int[] f=ComfortPoseGeometry.crop(pose,variant);ok(f[0]>=0&&f[1]>=0&&f[0]+f[2]<=1024&&f[1]+f[3]<=1536,"audited atlas face bounds");}
 for(int pose=0;pose<4;pose++){float[] mesh=new float[17*25*2];for(int row=0;row<=24;row++)for(int col=0;col<=16;col++){int k=(row*17+col)*2;mesh[k]=512f*col/16;mesh[k+1]=768f*row/24;}float[] original=mesh.clone();ComfortPoseGeometry.animate(mesh,16,24,pose,1400,0,0,1);boolean moved=false;for(int k=0;k<mesh.length;k++){ok(Math.abs(mesh[k]-original[k])<2,"bounded movement");if(mesh[k]!=original[k])moved=true;}ok(moved,"upper body animates");ComfortPoseGeometry.animate(original,16,24,pose,1400,1,800,0);for(int row=0;row<=24;row++)for(int col=0;col<=16;col++){int k=(row*17+col)*2;ok(original[k]==512f*col/16&&original[k+1]==768f*row/24,"motion disabled setting");}}
 ok(ComfortPoseGeometry.envelope(0)==0&&ComfortPoseGeometry.envelope(2800)==0,"finite entry");ok(ComfortPoseGeometry.expression(6)==1&&ComfortPoseGeometry.expression(7)==2&&ComfortPoseGeometry.expression(9)==3,"semantic facial families");System.out.println("PASS "+n+" comfort command/continuity/geometry/motion checks");}
}
